async function request(path,options={}){const r=await fetch(path,{cache:'no-store',...options,headers:{...headers,...options.headers}});let body=await r.json().catch(()=>({}));if(!r.ok){if(r.status===409)throw Error('This workspace changed in another tab. Your edits have not overwritten it. Export your current work, then reload to use the latest version.');throw Error(typeof body.error==='string'?body.error:'The workspace request failed. Your changes are still on this page.');}return body;}
